import React from 'react';

function ShowtimeScreen({ movie, showtimes, onSelectShowtime, onBack }) {
  const lichChieuCuaPhim = showtimes.filter(st => st.movie_id === movie.id);

  return (
    <div>
      <button className="btn mb-4 fw-bold text-white border-0" style={{ background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)' }} onClick={onBack}>⬅ Quay lại trang chủ</button>
      <div className="card p-4 shadow-sm border-0 bg-white">
        <h3 className="fw-bold mb-1" style={{ color: '#ec4899' }}>🎬 {movie.title}</h3>
        <p className="text-muted mb-4">Vui lòng chọn một suất chiếu phù hợp với thời gian của bạn:</p>
        
        <div className="row">
          {lichChieuCuaPhim.length > 0 ? (
            lichChieuCuaPhim.map((st) => (
              <div className="col-sm-6 col-md-4 mb-3" key={st.id}>
                <button className="btn btn-outline-primary p-3 w-100 text-start shadow-sm" onClick={() => onSelectShowtime(st)}>
                  <div className="fw-bold fs-6 text-dark">📅 Ngày: {st.show_date}</div>
                  <div className="fw-bold text-success fs-3 my-1">⏰ Giờ: {st.show_time}</div>
                  <hr className="my-2"/>
                  <div className="text-secondary small fw-bold">Giá vé: {st.ticket_price.toLocaleString()}đ</div>
                </button>
              </div>
            ))
          ) : (
            <div className="col-12 text-center py-4 text-muted">Hiện tại phim này chưa có lịch chiếu mới.</div>
          )}
        </div>
      </div>
    </div>
  );
}

export default ShowtimeScreen;
